SET NAMES utf8mb4;

-- =======================================================================
-- DẠNG NỐI GHÉP CÁC PHẦN TƯƠNG ỨNG (CQ_NOI_GHEP)
--
-- Bài 10 — BT-DNGTU01 — Russia's First Cancer Vaccine
-- Bài 11 — BT-DNGTU06 — Nyepi, the Balinese Day of Silence
--
-- Cấu trúc mỗi bài:
--   baitap.NoiDungNguCanhChung = bài đọc dùng chung — lưu MỘT lần
--   baitapcauhoi               = MỖI CÂU HỎI một dòng, có danh sách trái/phải riêng
--
-- Đáp án là ánh xạ id cột trái -> id cột phải.
-- Cột phải được xáo trộn để bài tập có ý nghĩa luyện tập.
-- =======================================================================

SET @MaKhoaHoc = (SELECT `MaKhoaHoc` FROM `khoahoc` LIMIT 1);

SET @LoaiCauHoi = (SELECT c.`MaChiTiet` FROM `chitietdanhmuc` c
    JOIN `nhomdanhmuc` n ON n.`MaNhom` = c.`MaNhom` AND n.`MaCode` = 'LOAI_CAU_HOI'
    WHERE c.`MaCode` = 'CQ_NOI_GHEP' LIMIT 1);
SET @MucDo = (SELECT c.`MaChiTiet` FROM `chitietdanhmuc` c
    JOIN `nhomdanhmuc` n ON n.`MaNhom` = c.`MaNhom` AND n.`MaCode` = 'MUC_DO'
    WHERE c.`MaCode` = 'TRUNG_BINH' LIMIT 1);
SET @KyNang = (SELECT c.`MaChiTiet` FROM `chitietdanhmuc` c
    JOIN `nhomdanhmuc` n ON n.`MaNhom` = c.`MaNhom` AND n.`MaCode` = 'KY_NANG'
    WHERE c.`MaCode` = 'KN_DOC' LIMIT 1);
SET @LoaiBaiTap = (SELECT c.`MaChiTiet` FROM `chitietdanhmuc` c
    JOIN `nhomdanhmuc` n ON n.`MaNhom` = c.`MaNhom` AND n.`MaCode` = 'LOAI_BAI_TAP'
    WHERE c.`MaCode` = 'HOMEWORK' LIMIT 1);

-- -----------------------------------------------------------------------
-- Ngan hang de chua cac bai tap mau nay. Tao neu chua co, lay lai neu da co,
-- de chay lai script khong sinh ngan hang trung.
-- -----------------------------------------------------------------------
SET @MaNganHang = (SELECT `MaNganHang` FROM `nganhangde`
    WHERE `MaKhoaHoc` = @MaKhoaHoc AND `DaXoa` = 0 LIMIT 1);

INSERT INTO `nganhangde`
    (`MaNganHang`, `MaKhoaHoc`, `MaCode`, `TenNganHang`, `MucDo`, `KyNang`,
     `Unit`, `MoTa`, `TrangThai`, `ThoiGianTao`, `DaXoa`)
SELECT UUID(), @MaKhoaHoc,
       CONCAT('NHD-', UPPER(SUBSTRING(REPLACE(@MaKhoaHoc, '-', ''), 1, 8))),
       CONCAT('Ngân hàng ', k.`TenKhoaHoc`),
       @MucDo, @KyNang, k.`TenKhoaHoc`,
       CONCAT('Ngân hàng đề của ', k.`TenKhoaHoc`),
       'ACTIVE', NOW(), 0
FROM `khoahoc` k
WHERE k.`MaKhoaHoc` = @MaKhoaHoc AND @MaNganHang IS NULL;

SET @MaNganHang = (SELECT `MaNganHang` FROM `nganhangde`
    WHERE `MaKhoaHoc` = @MaKhoaHoc AND `DaXoa` = 0 LIMIT 1);


-- =======================================================================
-- BÀI 10 — BT-DNGTU01 — Russia's First Cancer Vaccine
-- =======================================================================
SET @Bai10 = UUID();

INSERT INTO `baitap` (
    `MaBaiTap`, `MaKhoaHoc`, `MaNganHang`, `TenBaiTap`, `LaMauNganHang`,
    `LoaiBaiTap`, `LoaiCauHoi`, `MucDo`, `KyNang`,
    `HuongDanChung`, `NoiDungNguCanhChung`, `MoTa`,
    `ChoXemDapAnSauNop`, `TrangThai`, `DaXoa`, `ThoiGianTao`
) VALUES (
    @Bai10, @MaKhoaHoc, @MaNganHang,
    'Bài 10 — Nối ghép các phần tương ứng: Russia''s First Cancer Vaccine', 1,
    @LoaiBaiTap, @LoaiCauHoi, @MucDo, @KyNang,
    'Match each option in the left column with a corresponding option in the right column.',
    'Russia is on track to introduce its first cancer vaccine by early 2025, marking a significant milestone in medical innovation. This vaccine is developed by a Russian team in collaboration with major research institutions, including the Moscow State University and the Cancer Research Institute. It uses cutting-edge mRNA technology, which has already proven effective in COVID-19 vaccines, to target specific tumor cells and stimulate the body''s immune response to fight cancer more effectively.\n\nThe vaccine is currently undergoing the final stages of clinical trials. These trials are designed to evaluate its safety and efficacy in treating certain types of cancers, particularly those related to lung and liver, which are among the most common globally. Preliminary results suggest that this vaccine could significantly improve survival rates and reduce recurrence risks for cancer patients, bringing hope to millions worldwide.\n\nHowever, accessibility and affordability remain critical concerns. Experts highlight the potential challenge of high production costs, which may limit access to this life-saving innovation in lower-income regions. To address this, Russia is exploring partnerships with global health organizations and pharmaceutical companies to scale production and distribution. This effort aims to make the vaccine available to a broader population and integrate it into public health systems.\n\nThe introduction of this vaccine aligns with the growing global momentum in cancer prevention and treatment. Similar initiatives, such as trials conducted by BioNTech in the UK, underline the global effort to combat cancer with advanced technologies. If successful, Russia''s vaccine could complement these efforts, marking a new era in the fight against one of the world''s leading causes of death.',
    JSON_OBJECT('schema','ADMIN_ASSIGNMENT_V1','code','BT-DNGTU01','description',NULL,'status','APPROVED'),
    1, 1, 0, NOW()
);

INSERT INTO `baitapcauhoi` (`MaCauHoiDe`, `MaBaiTap`, `MaCauHoi`, `ThuTu`, `SoCau`, `DiemCuaCau`, `NoiDung`, `ThoiGianTao`) VALUES
(UUID(), @Bai10, NULL, 1, 'Câu 1', 1, '{"debai":{"cauHoiGoc":"Question 1. Choose the most appropriate summary sentences for each paragraph.","nhanTrai":"Paragraph","nhanPhai":"Abstract","danhSachTrai":[{"id":"t1","text":"Paragraph 1"},{"id":"t2","text":"Paragraph 2"},{"id":"t3","text":"Paragraph 3"},{"id":"t4","text":"Paragraph 4"}],"danhSachPhai":[{"id":"a","text":"The vaccine faces accessibility and affordability challenges, leading Russia to seek partnerships to expand production and distribution."},{"id":"b","text":"The vaccine''s potential success could contribute to global cancer treatment efforts and mark a new era in the fight against cancer."},{"id":"c","text":"Clinical trials are showing promising results, with the vaccine potentially improving survival rates and reducing cancer recurrence."},{"id":"d","text":"Russia''s new cancer vaccine uses mRNA technology and is being developed to target cancer cells and stimulate the immune system."}]},"dapan":{"t1":"d","t2":"c","t3":"a","t4":"b"},"giaithich":"Đoạn 1: Tác giả giới thiệu về vaccine ung thư đầu tiên của Nga, được phát triển bằng công nghệ mRNA tiên tiến.\\nĐoạn 2: Tác giả nói về giai đoạn thử nghiệm lâm sàng cuối cùng của vaccine.\\nĐoạn 3: Tác giả đề cập đến những vấn đề liên quan đến khả năng tiếp cận và khả năng chi trả.\\nĐoạn 4: Tác giả nhấn mạnh rằng vaccine của Nga là một phần trong nỗ lực toàn cầu chống lại bệnh ung thư.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","reading","health"]}', NOW()),
(UUID(), @Bai10, NULL, 2, 'Câu 2', 1, '{"debai":{"cauHoiGoc":"Question 2. Choose the equivalent phrase from the left and right columns.","nhanTrai":"The phrase","nhanPhai":"Equivalent phrase","danhSachTrai":[{"id":"t1","text":"cutting-edge"},{"id":"t2","text":"recurrence"},{"id":"t3","text":"affordability"},{"id":"t4","text":"Preliminary"}],"danhSachPhai":[{"id":"a","text":"Affordable"},{"id":"b","text":"Advanced"},{"id":"c","text":"Return"},{"id":"d","text":"Initial"}]},"dapan":{"t1":"b","t2":"c","t3":"a","t4":"d"},"giaithich":"cutting-edge (adj): tiên tiến, hiện đại = advanced (adj): tiên tiến.\\nrecurrence (noun): sự tái phát = return (noun): sự quay trở lại.\\naffordability (noun): khả năng chi trả = affordable (adj): có khả năng chi trả được.\\nPreliminary (adj): sơ bộ, ban đầu = initial (adj): ban đầu.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","vocabulary","synonym"]}', NOW()),
(UUID(), @Bai10, NULL, 3, 'Câu 3', 1, '{"debai":{"cauHoiGoc":"Question 3. Match the sentences from the left column with the sentences from the right column.","nhanTrai":"Column A","nhanPhai":"Column B","danhSachTrai":[{"id":"t1","text":"This vaccine is developed by a Russian team in collaboration with major research institutions, including the Moscow State University and the Cancer Research Institute."},{"id":"t2","text":"Preliminary results suggest that this vaccine could significantly improve survival rates and reduce recurrence risks for cancer patients, bringing hope to millions worldwide."},{"id":"t3","text":"Experts highlight the potential challenge of high production costs, which may limit access to this life-saving innovation in lower-income regions."},{"id":"t4","text":"If successful, Russia''s vaccine could complement these efforts, marking a new era in the fight against one of the world''s leading causes of death."}],"danhSachPhai":[{"id":"a","text":"The vaccine could contribute to a new era in the global fight against cancer."},{"id":"b","text":"High production costs could make the vaccine less accessible to people in poorer regions."},{"id":"c","text":"The vaccine may improve survival rates and reduce the chance of cancer returning."},{"id":"d","text":"The vaccine is being developed by Russian researchers with the support of major research institutions."}]},"dapan":{"t1":"d","t2":"c","t3":"b","t4":"a"},"giaithich":"1. Hai câu đều thể hiện rằng vaccine được phát triển bởi các nhà nghiên cứu Nga với sự hợp tác của các tổ chức nghiên cứu lớn.\\n2. reduce recurrence risks = giảm nguy cơ tái phát; reduce the chance of cancer returning = giảm khả năng ung thư quay trở lại.\\n3. high production costs = chi phí sản xuất cao; less accessible = khó tiếp cận hơn.\\n4. complement these efforts = góp phần vào những nỗ lực này; marking a new era = đánh dấu một kỷ nguyên mới.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","paraphrase"]}', NOW());


-- =======================================================================
-- BÀI 11 — BT-DNGTU06 — Nyepi, the Balinese Day of Silence
-- =======================================================================
SET @Bai11 = UUID();

INSERT INTO `baitap` (
    `MaBaiTap`, `MaKhoaHoc`, `MaNganHang`, `TenBaiTap`, `LaMauNganHang`,
    `LoaiBaiTap`, `LoaiCauHoi`, `MucDo`, `KyNang`,
    `HuongDanChung`, `NoiDungNguCanhChung`, `MoTa`,
    `ChoXemDapAnSauNop`, `TrangThai`, `DaXoa`, `ThoiGianTao`
) VALUES (
    @Bai11, @MaKhoaHoc, @MaNganHang,
    'Bài 11 — Nối ghép các phần tương ứng: Nyepi, the Balinese Day of Silence', 1,
    @LoaiBaiTap, @LoaiCauHoi, @MucDo, @KyNang,
    'Match each option in the left column with a corresponding option in the right column.',
    '(I) Nestling within dynamic Balinese culture comes one of the world''s most intriguing and peculiar events: Nyepi. The Balinese New Year, better known as Nyepi, doesn''t involve parties or fireworks. (II) This follows with a deep silent day of self-meditation and spiritual cleansing (III). It is a holy day, derived from the Saka Calendar, when the predominantly Hindu population of this island gets an opportunity to reunite with their inner self and their gods. (IV)\n\nThe preparation for Nyepi starts days in advance, with the execution of various colored and meaningful rituals. The most interesting include an Ogoh-Ogoh parade where huge and artistic statues, which represent evil spirits, are taken along the streets. Made from bamboo and paper, these statues constitute both kinds of artistic work and forms of exorcising the island from all negative feelings. The Ogoh-Ogoh figures are ritually burned in a spectacular display as the sun is setting, a ritual that symbolizes destruction to evil spirits and spiritual rejuvenation.\n\nBut on Nyepi Day itself, the island is supposed to be in full stillness-no flights, no traffic, no lights, and no noise. Even tourists are encouraged to stay indoors and minimize activities by this convention. The streets are empty; it is a case whereby the island stood still, holding its breath. This silence amongst the Balinese people is an inside thing, deeply. They go into meditation, fasting, and reflection on life for a balance between good and evil in themselves. The silence is said to deceive the evil spirits that the island is indeed uninhabited, thus offering protection for the forthcoming year.\n\nMore than a religious holiday, Nyepi is deeply enriching in culture and spirituality, underlining the values of harmony and introspection particular to the Balinese. For any visitor, the experience of Nyepi is at once an exercise in humility and a source of inspiration. A stepping back from the din of modern life into the emotive power of silence, leaving with great respect for timeless traditions and the never-failing devotion of the people to beliefs.\n\n(Adapted from viceroybali)',
    JSON_OBJECT('schema','ADMIN_ASSIGNMENT_V1','code','BT-DNGTU06','description',NULL,'status','APPROVED'),
    1, 1, 0, NOW()
);

INSERT INTO `baitapcauhoi` (`MaCauHoiDe`, `MaBaiTap`, `MaCauHoi`, `ThuTu`, `SoCau`, `DiemCuaCau`, `NoiDung`, `ThoiGianTao`) VALUES

(UUID(), @Bai11, NULL, 1, 'Câu 1', 1, '{"debai":{"cauHoiGoc":"Question 1. Choose the most appropriate summary sentences for each paragraph.","nhanTrai":"Paragraph","nhanPhai":"Abstract","danhSachTrai":[{"id":"t1","text":"Paragraph 1"},{"id":"t2","text":"Paragraph 2"},{"id":"t3","text":"Paragraph 3"},{"id":"t4","text":"Paragraph 4"}],"danhSachPhai":[{"id":"a","text":"The preparation for Nyepi involves colorful rituals, including the Ogoh-Ogoh parade and the burning of symbolic statues."},{"id":"b","text":"Nyepi is a unique Balinese New Year celebration characterized by silence, meditation, and spiritual cleansing."},{"id":"c","text":"Nyepi offers visitors a meaningful cultural and spiritual experience while highlighting Balinese values and traditions."},{"id":"d","text":"On Nyepi Day, the entire island becomes silent as people stay indoors, meditate, fast, and reflect on life."}]},"dapan":{"t1":"b","t2":"a","t3":"d","t4":"c"},"giaithich":"Đoạn 1: Đoạn văn giới thiệu về Nyepi, một sự kiện đặc biệt trong văn hóa Bali. Đây là năm mới của người Bali, không có tiệc tùng hay pháo hoa mà thay vào đó là một ngày im lặng, thiền định và thanh lọc tâm linh.\\nĐoạn 2: Đoạn văn mô tả quá trình chuẩn bị cho Nyepi. Các nghi lễ đầy màu sắc được tổ chức, nổi bật là cuộc diễu hành Ogoh-Ogoh với những bức tượng lớn tượng trưng cho các linh hồn ma quỷ, sau đó những bức tượng này được đốt để tượng trưng cho việc tiêu diệt cái ác và tái sinh tinh thần.\\nĐoạn 3: Đoạn văn mô tả Nyepi Day, khi toàn bộ hòn đảo chìm trong sự tĩnh lặng. Không có chuyến bay, giao thông, ánh sáng hay tiếng ồn. Người dân thiền định, nhịn ăn và suy ngẫm về cuộc sống nhằm tìm kiếm sự cân bằng giữa cái thiện và cái ác.\\nĐoạn 4: Đoạn văn nhấn mạnh ý nghĩa văn hóa và tinh thần sâu sắc của Nyepi. Đây không chỉ là một ngày lễ tôn giáo mà còn thể hiện các giá trị về sự hòa hợp và hướng nội của người Bali, đồng thời mang đến cho du khách một trải nghiệm đầy cảm hứng.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","reading","balinese_culture"]}', NOW()),

(UUID(), @Bai11, NULL, 2, 'Câu 2', 1, '{"debai":{"cauHoiGoc":"Question 2. Choose the equivalent phrase from the left and right columns.","nhanTrai":"The phrase","nhanPhai":"Equivalent phrase","danhSachTrai":[{"id":"t1","text":"peculiar"},{"id":"t2","text":"introspection"},{"id":"t3","text":"spiritual cleansing"},{"id":"t4","text":"stillness"}],"danhSachPhai":[{"id":"a","text":"Unique"},{"id":"b","text":"Spiritual purification"},{"id":"c","text":"Silence"},{"id":"d","text":"Self-reflection"}]},"dapan":{"t1":"a","t2":"d","t3":"b","t4":"c"},"giaithich":"peculiar /pɪˈkjuː.li.ər/ (adj): kỳ lạ, đặc biệt = unique /juːˈniːk/ (adj): độc đáo, đặc biệt.\\nOne of the world''s most intriguing and peculiar events.\\n→ Một trong những sự kiện hấp dẫn và độc đáo nhất thế giới.\\n\\nintrospection /ˌɪn.trəˈspek.ʃən/ (noun): sự tự suy ngẫm = self-reflection /ˌself.rɪˈflek.ʃən/ (noun): sự tự nhìn nhận, tự suy ngẫm.\\nNyepi underlines the values of harmony and introspection.\\n→ Nyepi nhấn mạnh các giá trị về sự hòa hợp và sự tự suy ngẫm.\\n\\nspiritual cleansing (noun): sự thanh lọc tâm linh = spiritual purification (noun): sự thanh lọc tâm linh.\\nThis follows with a deep silent day of self-meditation and spiritual cleansing.\\n→ Tiếp theo là một ngày im lặng sâu sắc dành cho thiền định và thanh lọc tâm linh.\\n\\nstillness /ˈstɪl.nəs/ (noun): sự tĩnh lặng = silence /ˈsaɪ.ləns/ (noun): sự im lặng.\\nThe island is supposed to be in full stillness.\\n→ Hòn đảo được cho là hoàn toàn chìm trong sự tĩnh lặng.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","vocabulary","synonym"]}', NOW()),

(UUID(), @Bai11, NULL, 3, 'Câu 3', 1, '{"debai":{"cauHoiGoc":"Question 3. Match the sentences from the left column with the sentences from the right column.","nhanTrai":"Column A","nhanPhai":"Column B","danhSachTrai":[{"id":"t1","text":"This follows with a deep silent day of self-meditation and spiritual cleansing. (II)"},{"id":"t2","text":"The Ogoh-Ogoh figures are ritually burned in a spectacular display as the sun is setting, a ritual that symbolizes destruction to evil spirits and spiritual rejuvenation."},{"id":"t3","text":"The island is supposed to be in full stillness-no flights, no traffic, no lights, and no noise."},{"id":"t4","text":"They go into meditation, fasting, and reflection on life for a balance between good and evil in themselves."}],"danhSachPhai":[{"id":"a","text":"People use meditation, fasting, and reflection to seek inner balance."},{"id":"b","text":"The island becomes completely quiet with no transportation, lights, or noise."},{"id":"c","text":"The burning of the statues represents the destruction of evil and spiritual renewal."},{"id":"d","text":"Nyepi is followed by a silent day dedicated to spiritual purification and self-meditation."}]},"dapan":{"t1":"d","t2":"c","t3":"b","t4":"a"},"giaithich":"[DỊCH]\\n1. This follows with a deep silent day of self-meditation and spiritual cleansing. (II)\\nNyepi is followed by a silent day dedicated to spiritual purification and self-meditation.\\nTiếp theo là một ngày im lặng sâu sắc dành cho việc tự thiền định và thanh lọc tâm linh.\\n→ self-meditation = tự thiền định; spiritual cleansing = spiritual purification = thanh lọc tâm linh.\\n\\n2. The Ogoh-Ogoh figures are ritually burned... a ritual that symbolizes destruction to evil spirits and spiritual rejuvenation.\\nThe burning of the statues represents the destruction of evil and spiritual renewal.\\n→ destruction to evil spirits = sự tiêu diệt các linh hồn ma quỷ; spiritual rejuvenation = spiritual renewal = sự đổi mới tinh thần.\\n\\n3. The island is supposed to be in full stillness-no flights, no traffic, no lights, and no noise.\\nThe island becomes completely quiet with no transportation, lights, or noise.\\n→ full stillness = hoàn toàn tĩnh lặng; completely quiet = hoàn toàn yên tĩnh.\\n\\n4. They go into meditation, fasting, and reflection on life for a balance between good and evil in themselves.\\nPeople use meditation, fasting, and reflection to seek inner balance.\\n→ reflection on life = suy ngẫm về cuộc sống; seek inner balance = tìm kiếm sự cân bằng nội tâm.\\n\\n[DỊCH BÀI]\\nĐoạn 1\\nẨn mình trong nền văn hóa năng động của Bali là một trong những sự kiện hấp dẫn và đặc biệt nhất thế giới: Nyepi. Năm mới của người Bali, được biết đến nhiều hơn với tên gọi Nyepi, không bao gồm các bữa tiệc hay pháo hoa. Tiếp theo đó là một ngày im lặng sâu sắc dành cho việc tự thiền định và thanh lọc tâm linh. Đây là một ngày lễ linh thiêng, bắt nguồn từ Lịch Saka, khi phần lớn dân số theo đạo Hindu trên hòn đảo này có cơ hội kết nối lại với bản thân bên trong và các vị thần của họ.\\n\\nĐoạn 2\\nViệc chuẩn bị cho Nyepi bắt đầu từ nhiều ngày trước, với việc thực hiện nhiều nghi lễ đầy màu sắc và ý nghĩa. Điều thú vị nhất là cuộc diễu hành Ogoh-Ogoh, trong đó những bức tượng khổng lồ và nghệ thuật, tượng trưng cho các linh hồn ma quỷ, được đưa đi dọc các con phố. Được làm từ tre và giấy, những bức tượng này vừa là những tác phẩm nghệ thuật vừa là một hình thức xua đuổi mọi cảm xúc tiêu cực khỏi hòn đảo. Các hình tượng Ogoh-Ogoh được đốt theo nghi lễ trong một màn trình diễn ngoạn mục khi mặt trời lặn, một nghi lễ tượng trưng cho việc tiêu diệt các linh hồn ma quỷ và sự tái sinh về mặt tinh thần.\\n\\nĐoạn 3\\nNhưng vào chính ngày Nyepi, hòn đảo được cho là hoàn toàn chìm trong sự tĩnh lặng — không có chuyến bay, không có giao thông, không có ánh sáng và không có tiếng ồn. Ngay cả khách du lịch cũng được khuyến khích ở trong nhà và hạn chế các hoạt động theo quy định này. Đường phố vắng tanh; hòn đảo dường như đứng yên, nín thở. Sự im lặng này đối với người Bali mang ý nghĩa sâu sắc từ bên trong. Họ thiền định, nhịn ăn và suy ngẫm về cuộc sống để tìm kiếm sự cân bằng giữa cái thiện và cái ác trong chính mình. Người ta tin rằng sự im lặng này đánh lừa các linh hồn ma quỷ, khiến chúng nghĩ rằng hòn đảo không có người sinh sống, từ đó mang lại sự bảo vệ cho năm sắp tới.\\n\\nĐoạn 4\\nKhông chỉ là một ngày lễ tôn giáo, Nyepi còn mang ý nghĩa sâu sắc về văn hóa và tinh thần, nhấn mạnh các giá trị về sự hòa hợp và hướng nội đặc trưng của người Bali. Đối với bất kỳ du khách nào, trải nghiệm Nyepi vừa là một bài học về sự khiêm nhường vừa là nguồn cảm hứng. Đó là sự tạm rời xa những ồn ào của cuộc sống hiện đại để cảm nhận sức mạnh đầy cảm xúc của sự im lặng, đồng thời rời đi với sự tôn trọng sâu sắc đối với những truyền thống lâu đời và lòng tận tụy không ngừng của người dân đối với niềm tin của họ.","loai":"CQ_NOI_GHEP","la_tu_luan":false,"tags":["matching","paraphrase","balinese_culture"]}', NOW());
